def m(tex):
 if r'\begin' not in tex:
  relations=list(__import__('re').finditer(r'\\approx|=',tex))
  if len(relations)>1:
   first,last=relations[0],relations[-1]
   tex=r'\begin{aligned}'+tex[:first.start()]+'&'+tex[first.start():last.start()]+r'\\&'+tex[last.start():]+r'\end{aligned}'
 return H['m'](tex)
